package com.srent.dispute;
import com.srent.audit.AuditService;import com.srent.booking.*;import com.srent.common.ApiException;import com.srent.security.CurrentUser;import com.srent.storage.StorageService;import com.srent.user.UserRepository;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import lombok.RequiredArgsConstructor;import org.springframework.data.domain.*;import org.springframework.data.web.PageableDefault;import org.springframework.http.*;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.bind.annotation.*;import java.time.Instant;import java.util.*;
@RestController @RequestMapping("/api/v1/disputes") @RequiredArgsConstructor
public class DisputeController{private final DisputeRepository disputes;private final DisputeEvidenceRepository evidence;private final BookingRepository bookings;private final UserRepository users;private final StorageService storage;private final AuditService audit;public record Request(@NotNull UUID bookingId,@NotBlank @Size(max=180)String subject,@NotBlank @Size(max=5000)String description){}public record Response(UUID id,UUID bookingId,String subject,String description,String landlordResponse,Dispute.Status status,String adminNote,Instant createdAt){public static Response from(Dispute d){return new Response(d.getId(),d.getBooking().getId(),d.getSubject(),d.getDescription(),d.getLandlordResponse(),d.getStatus(),d.getAdminNote(),d.getCreatedAt());}}public record Text(@NotBlank @Size(max=5000)String content){}public record EvidenceRequest(@NotBlank String contentType){}
@PostMapping @ResponseStatus(HttpStatus.CREATED)@Transactional public Response create(@Valid@RequestBody Request q){var b=bookings.findById(q.bookingId()).orElseThrow(()->ApiException.notFound("Booking"));if(!b.getStudent().getId().equals(CurrentUser.id()))throw ApiException.forbidden("Chỉ sinh viên của booking có thể tạo khiếu nại");var d=new Dispute();d.setBooking(b);d.setCreatedBy(users.getReferenceById(CurrentUser.id()));d.setSubject(q.subject());d.setDescription(q.description());disputes.save(d);audit.log(CurrentUser.id(),"DISPUTE_CREATED","DISPUTE",d.getId(),null);return Response.from(d);}
@GetMapping public Page<Response> list(@PageableDefault(size=20,sort="createdAt",direction=Sort.Direction.DESC)Pageable p){return disputes.findForUser(CurrentUser.id(),p).map(Response::from);}
@PatchMapping("/{id}/respond")@Transactional public Response respond(@PathVariable UUID id,@Valid@RequestBody Text q){var d=access(id);if(!d.getBooking().getLandlord().getId().equals(CurrentUser.id()))throw ApiException.forbidden("Chỉ chủ trọ liên quan được phản hồi");d.setLandlordResponse(q.content());d.setStatus(Dispute.Status.IN_REVIEW);audit.log(CurrentUser.id(),"DISPUTE_RESPONDED","DISPUTE",id,null);return Response.from(d);}
@PostMapping("/{id}/evidence/upload-request")@Transactional(readOnly=true) public StorageService.Upload upload(@PathVariable UUID id,@Valid@RequestBody EvidenceRequest q){access(id);return storage.presignedUpload(true,"disputes/"+id+"/"+CurrentUser.id()+"/"+UUID.randomUUID(),q.contentType());}
public record EvidenceComplete(@NotBlank String objectKey,@NotBlank String contentType){}public record EvidenceResponse(UUID id,String contentType,String downloadUrl){}
@PostMapping("/{id}/evidence/complete")@Transactional public EvidenceResponse evidenceComplete(@PathVariable UUID id,@Valid@RequestBody EvidenceComplete q){var d=access(id);String prefix="disputes/"+id+"/"+CurrentUser.id()+"/";if(!q.objectKey().startsWith(prefix))throw ApiException.forbidden("Tệp bằng chứng không thuộc người dùng hoặc khiếu nại này");storage.stat(true,q.objectKey());var e=new DisputeEvidence();e.setDispute(d);e.setUploadedBy(users.getReferenceById(CurrentUser.id()));e.setObjectKey(q.objectKey());e.setContentType(q.contentType());evidence.save(e);audit.log(CurrentUser.id(),"DISPUTE_EVIDENCE_ADDED","DISPUTE",id,null);return new EvidenceResponse(e.getId(),e.getContentType(),storage.presignedDownload(e.getObjectKey()));}
private Dispute access(UUID id){var d=disputes.findById(id).orElseThrow(()->ApiException.notFound("Khiếu nại"));UUID u=CurrentUser.id();if(!d.getBooking().getStudent().getId().equals(u)&&!d.getBooking().getLandlord().getId().equals(u))throw ApiException.forbidden("Không có quyền truy cập khiếu nại");return d;}}
